worse.tests/slugify.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { slugify } from "../src/slugify.ts";

test("applies the same replace chain the implementation applies", () => {
  const input = "Hello World";
  const expected = input
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
  assert.equal(slugify(input), expected);
});

test("applies the same replace chain on punctuation", () => {
  const input = "!!hello!!";
  const expected = input
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
  assert.equal(slugify(input), expected);
});
